import{_ as o,I as n,o as s,c as i,j as t,a,J as h,a6 as d}from"./chunks/framework.9ylqSDY5.js";const v=JSON.parse('{"title":"Control Room","description":"","frontmatter":{"title":"Control Room","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/observing/control-room.md","filePath":"guides/observing/control-room.md"}'),l={name:"guides/observing/control-room.md"};function c(g,e,u,m,p,f){const r=n("ToolShot");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"control-room",tabindex:"-1"},[a("Control Room "),t("a",{class:"header-anchor",href:"#control-room","aria-label":"Permalink to “Control Room”"},"​")],-1)),e[1]||(e[1]=t("blockquote",null,[t("p",null,"Automate your data acquisition, integrated with your data pipelines.")],-1)),e[2]||(e[2]=t("p",null,[a("The "),t("strong",null,"Control Room"),a(" drives your equipment and takes your data. It runs on your own infrastructure, talks directly to the devices of your observatory, and files every frame in "),t("a",{href:"/guides/data/"},"Data Grand Central"),a(".")],-1)),h(r,{tool:"observer-console","no-caption":""}),e[3]||(e[3]=d('<h2 id="the-seven-tools" tabindex="-1">The seven tools <a class="header-anchor" href="#the-seven-tools" aria-label="Permalink to “The seven tools”">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Tool</th></tr></thead><tbody><tr><td>Register, connect, check or move a device</td><td><a href="./equipment-registry">Equipments Registry</a></td></tr><tr><td>Observe by hand, now</td><td><a href="./observer-console">Observer Console</a></td></tr><tr><td>Automate a whole night</td><td><a href="./night-scheduler">Night Scheduler</a></td></tr><tr><td>React to gamma-ray bursts and other transients</td><td><a href="./too-policies">Targets of Opportunity</a></td></tr><tr><td>Take biases, darks and dome flats</td><td><a href="./calibration-manager">Calibration Manager</a></td></tr><tr><td>Close the observatory when conditions turn bad</td><td><a href="./safety-configuration">Safety Configuration</a></td></tr><tr><td>Measure and correct a polar alignment</td><td><a href="./polar-alignment">Polar Alignment</a></td></tr></tbody></table><h2 id="before-the-first-night" tabindex="-1">Before the first night <a class="header-anchor" href="#before-the-first-night" aria-label="Permalink to “Before the first night”">​</a></h2><ol><li><strong>Start an Alpaca server</strong> on the machine your devices are plugged into. Arcsecond only needs its address. If it is not the machine running Arcsecond.local, see <a href="/guides/operating/alpaca-lan">Alpaca server on another machine</a>.</li><li><strong>Register the devices</strong> in the <a href="./equipment-registry">Equipments Registry</a>.</li><li><strong>Define an observing setup</strong>: a telescope, and the equipment used with it.</li><li><strong>Check the safety rules</strong> in <a href="./safety-configuration">Safety Configuration</a>.</li><li><strong>Observe</strong> from the <a href="./observer-console">Observer Console</a>. Once that works, automate with the <a href="./night-scheduler">Night Scheduler</a>.</li></ol><h2 id="equipment-device-setup" tabindex="-1">Equipment, device, setup <a class="header-anchor" href="#equipment-device-setup" aria-label="Permalink to “Equipment, device, setup”">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Device</strong></td><td>What an Alpaca server exposes: the driver Arcsecond connects to.</td></tr><tr><td><strong>Equipment</strong></td><td>The telescope, camera or dome itself, which observations and metadata are attached to. Its device can be replaced, and the equipment stays the same.</td></tr><tr><td><strong>Observing setup</strong></td><td>A telescope and the equipment used with it. The Observer Console and the Night Scheduler work on one setup.</td></tr></tbody></table><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to “The status bar”">​</a></h2><p>The bar at the bottom stays there in every tool. It holds:</p><ul><li>the <strong>connection</strong> to the server, and a check of all equipment at once;</li><li>the <strong>observing setup</strong> in use;</li><li>the <strong>interrupts</strong> switch, which allows <a href="./too-policies">transient alerts</a> to take that setup;</li><li>the <strong>observer</strong> in control. One person controls a setup at a time: take control, request it, hand it over or release it here;</li><li>the <strong>night log</strong> and the <strong>dataset</strong> of the night;</li><li>webcams, all-sky images and the live stream of operations.</li></ul><h2 id="where-the-data-goes" tabindex="-1">Where the data goes <a class="header-anchor" href="#where-the-data-goes" aria-label="Permalink to “Where the data goes”">​</a></h2><p>Frames taken from the Observer Console and the Night Scheduler are saved in a dataset, and attached to the night log of the telescope, which records the activity of the night. Both are one click away in the status bar. Frames taken from the Equipments Registry are not filed: download them there.</p><p>Who may do what is on the <a href="/reference/permissions">Roles and permissions</a> page.</p>',12))])}const y=o(l,[["render",c]]);export{v as __pageData,y as default};
